def main(out):
    tp={r['repo']:r for r in csv.DictReader(open(f"{SC}/dev/throughput.csv"))}
    rows=[]
    for repo,(lic,purpose,build,test,tags,status,rel,ev,notes) in R.items():
        d=loc[repo]
        rev=subprocess.run(['git','-C',f'{EC}/{repo}','rev-parse','--short','HEAD'],capture_output=True,text=True).stdout.strip()
        rows.append(dict(repo=repo,rev=rev,licence=lic,purpose=purpose,
            languages="; ".join(f"{k} {v}" for k,v in d['code_by_lang'].items()),loc=d['code_loc'],
            test_count=f"static markers {d['test_case_markers']} in {d['test_files']} test files",
            build_result=build,test_result=test,capability_tags=tags,status=status,daf_relevance=rel,evidence_paths=ev,
            notes=(notes+f" Commits {tp[repo]['commits']}, active days {tp[repo]['active_days']}, agent-signal {tp[repo]['pct_commits_agent_signal']}%.").strip()))
    with open(out,'w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)
    print(len(rows))
main(sys.argv[1])
